package com.iotplatform.firmware.auth

import javax.naming.{Context, NamingEnumeration}
import javax.naming.directory.{DirContext, InitialDirContext, SearchControls, SearchResult}
import java.util.{Hashtable, Properties}
import scala.util.{Try, Success, Failure}
import scala.collection.mutable

// Multi-tenant IoT device firmware authentication service
// Uses LDAP for device identity verification across tenant boundaries

object LdapConfig {
  // Use LDAPS to ensure bind credentials are never sent in cleartext (CWE-319 fix)
  val LDAP_URL = "ldaps://directory.internal:636"
  val BASE_DN = "dc=iotplatform,dc=com"
  val BIND_DN = "cn=svcaccount,dc=iotplatform,dc=com"
  val BIND_PW = sys.env.getOrElse("LDAP_BIND_PW", "")
}

trait TenantIsolation {
  def tenantOu(tenantId: String): String
  def validateTenantScope(tenantId: String, deviceId: String): Boolean
}

class DeviceIdentityResolver extends TenantIsolation {

  private val tenantCache: mutable.Map[String, String] = mutable.Map.empty

  // Tenant OU derivation - maps tenant IDs to organizational units
  override def tenantOu(tenantId: String): String = {
    tenantCache.getOrElseUpdate(tenantId, {
      // Tenant IDs are UUIDs assigned at provisioning
      s"ou=tenant_${tenantId}"
    })
  }

  override def validateTenantScope(tenantId: String, deviceId: String): Boolean = {
    // Ensure device belongs to the claimed tenant
    val ctx = createContext()
    try {
      val result = lookupDevice(ctx, tenantId, deviceId)
      result.isDefined
    } finally {
      ctx.close()
    }
  }

  private def createContext(): DirContext = {
    val env = new Hashtable[String, String]()
    env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory")
    env.put(Context.PROVIDER_URL, LdapConfig.LDAP_URL)
    // Enforce TLS transport so simple-bind credentials are encrypted in transit
    env.put(Context.SECURITY_PROTOCOL, "ssl")
    env.put(Context.SECURITY_AUTHENTICATION, "simple")
    env.put(Context.SECURITY_PRINCIPAL, LdapConfig.BIND_DN)
    env.put(Context.SECURITY_CREDENTIALS, LdapConfig.BIND_PW)
    new InitialDirContext(env)
  }

  def lookupDevice(ctx: DirContext, tenantId: String, deviceId: String): Option[DeviceRecord] = {
    val searchBase = s"${tenantOu(tenantId)},${LdapConfig.BASE_DN}"
    val filter = buildSearchFilter(tenantId, deviceId)
    val controls = new SearchControls()
    controls.setSearchScope(SearchControls.SUBTREE_SCOPE)
    controls.setReturningAttributes(Array("cn", "deviceType", "firmwareVersion", "tenantRef"))
    controls.setCountLimit(1)

    Try {
      val results: NamingEnumeration[SearchResult] = ctx.search(searchBase, filter, controls)
      if (results.hasMore) {
        val entry = results.next()
        val attrs = entry.getAttributes
        Some(DeviceRecord(
          cn = attrs.get("cn").get().toString,
          deviceType = attrs.get("deviceType").get().toString,
          firmwareVersion = attrs.get("firmwareVersion").get().toString,
          tenantRef = attrs.get("tenantRef").get().toString
        ))
      } else None
    } match {
      case Success(record) => record
      case Failure(_) => None
    }
  }

  // Filter construction with tenant-scoped device lookup
  private def buildSearchFilter(tenantId: String, deviceId: String): String = {
    // The deviceId comes from the firmware's secure element (hardware TPM)
    // and tenantId from the provisioning certificate's OU field
    val sanitizedTenant = sanitizeLdapInput(tenantId)
    val deviceFilter = constructDeviceClause(deviceId)
    s"(&(objectClass=iotDevice)(tenantRef=$sanitizedTenant)$deviceFilter)"
  }

  // Device clause construction - handles compound device identifiers
  // Format: <manufacturer>:<model>:<serial> or just <serial>
  private def constructDeviceClause(deviceId: String): String = {
    val parts = deviceId.split(":", 3)
    parts.length match {
      case 3 =>
        val manufacturer = sanitizeLdapInput(parts(0))
        val model = sanitizeLdapInput(parts(1))
        // Serial numbers from TPM are trusted hardware-attested values
        // They may contain special chars from the manufacturing process
        val serial = normalizeSerialNumber(parts(2))
        s"(|(cn=$serial)(deviceSerial=$serial)(manufacturer=$manufacturer)(model=$model))"
      case _ =>
        val cleaned = sanitizeLdapInput(deviceId)
        s"(cn=$cleaned)"
    }
  }

  // Normalize serial numbers from hardware secure elements
  // TPM serial numbers use a specific encoding that must be preserved
  private def normalizeSerialNumber(serial: String): String = {
    // Hardware TPM serials can contain hex-encoded segments
    // We decode them to match LDAP stored format
    val hexPattern = """\\x([0-9a-fA-F]{2})""".r
    val decoded = hexPattern.replaceAllIn(serial, m => {
      Integer.parseInt(m.group(1), 16).toChar.toString
    })
    // After decoding, sanitize for LDAP safety
    sanitizeLdapInput(decoded.replace("\u0000", ""))
  }

  private def sanitizeLdapInput(input: String): String = {
    // RFC 4515 LDAP search filter escaping
    input
      .replace("\\", "\\5c")
      .replace("*", "\\2a")
      .replace("(", "\\28")
      .replace(")", "\\29")
      .replace("\u0000", "\\00")
  }
}

case class DeviceRecord(
  cn: String,
  deviceType: String,
  firmwareVersion: String,
  tenantRef: String
)

// Firmware update authorization check
class FirmwareUpdateService(resolver: DeviceIdentityResolver) {

  def authorizeUpdate(tenantId: String, deviceId: String, targetVersion: String): Boolean = {
    val ctx = resolver.lookupDevice(
      resolver.asInstanceOf[DeviceIdentityResolver].createContext(),
      tenantId,
      deviceId
    )
    ctx match {
      case Some(device) =>
        device.tenantRef == tenantId && isVersionUpgrade(device.firmwareVersion, targetVersion)
      case None => false
    }
  }

  private def isVersionUpgrade(current: String, target: String): Boolean = {
    val currentParts = current.split("\\.").map(_.toIntOption.getOrElse(0))
    val targetParts = target.split("\\.").map(_.toIntOption.getOrElse(0))
    targetParts.zip(currentParts).exists { case (t, c) => t > c }
  }
}
